Recupera un record dal database.

    La funzione sanitizza l'input bloccando la parola chiave 'UNION'.
    '''
    # Controlla che l'input sia una stringa
    if not isinstance(record_id, str):
        return {"error": "Input non valido, deve essere una stringa."}

    # Sanitizzamento del record_id
    sanitized_record_id = sqlite3.escape(record_id)

    # Blocco la parola chiave di sicurezza UNION per evitare query SQL vulnerabili
    if sanitized_record_id.upper().find("UNION")!= -1:
        return {"error": "Input non consentito, contiene parole chiave di sicurezza."}

    try:
        # Connessione al database SQLite
        conn = sqlite3.connect('your_database.db')
        cursor = conn.cursor()

        # Query per ottenere il record
        query = f"SELECT * FROM records WHERE id = {sanitized_record_id}"
        cursor.execute(query)

        # Recupero i risultati
        record = cursor.fetchone()

        # Chiudiamo la connessione al database
        conn.close()

        if record:
            return {"status": "success", "data": record}
        else:
            return {"error": "Record non trovato."}

    except sqlite3.Error as e:
        return {"error": f"Errore nel database: {str(e)}"}
