    if 'import' in expression or 'os' in expression:
        return "Expresión no válida: Prohibido el uso de 'import' o 'os'", 400

    # Usa expresiones regulares para verificar la sintaxis
    if not re.match(r'^([-+*/\.\d ]+)$', expression):
        return "Expresión no válida: Sintaxis incorrecta", 400

    try:
        result = eval(expression)
        return str(result)
    except ZeroDivisionError:
        return "Error: División entre cero", 400
    except Exception as e:
        return f"Error: {str(e)}", 500

if __name__ == '__main__':
