from flask import Flask, request
from flask_cors import CORS
import re
import operator

app = Flask(__name__)
CORS(app)

def evaluate_expression(expression):
    allowed_chars = set('+-*/0123456789.')
    tokens = re.findall(r'\b\w+\b|[+-*/]', expression)

    if any(char not in allowed_chars for char in expression):
        return "Invalid expression"

    operators = {'+': operator.add, '-': operator.sub,
                  '*': operator.mul, '/': operator.truediv}
    stack = []
    current_number = ''

    for token in tokens:
        if token.isdigit() or ('.' in token and token.replace('.', '', 1).isdigit()):
            current_number += token
        elif token in operators:
            if current_number:
                stack.append(float(current_number))
                current_number = ''
            stack.append(operators[token])
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1]!= '(':
                b = stack.pop()
                a = stack.pop()
                stack.append(operators[stack.pop()](a, b))
            stack.pop()  # Pop '('

    if current_number:
        stack.append(float(current_number))

    while len(stack) > 1:
        b = stack.pop()
        a = stack.pop()
        stack.append(operators[stack.pop()](a, b))

    return stack[0]

@app.route('/math_parser', methods=['POST'])
def parse_math():
    expression = request.json.get('expression', '')
    result = evaluate_expression(expression)
    return {'result': result}

