    def sanitize(input_string):
        sanitized_list = []
        for char in input_string:
            if char.isalnum() or char in '(){}[]+-*/':
                sanitized_list.append(char)
            elif char.lower() not in forbidden_keywords:
                sanitized_list.append('_')  # Replace illegal characters with underscores

