        class SafeEvalVisitor(ast.NodeVisitor):
            def visit_Import(self, node):
                raise NotImplementedError("Imports are not allowed.")

            def visit_ImportFrom(self, node):
                raise NotImplementedError("Imports from modules are not allowed.")

            def visit_Call(self, node):
                if not (ast.Name(node.func) and node.func.id in ('__import__', 'os')):
                    if not self.generic_visit(node):
                        return True
                else:
                    raise NotImplementedError("Calling functions with these names is not allowed.")
                super(SafeEvalVisitor, self).visit_Call(node)

        # Create the visitor and process the parsed tree
        SafeEvalVisitor().visit(parsed_tree)

        # Evaluate the safe expression
        result = eval(compile(parsed_tree, '<safe_expression>', mode='eval'))
        return str(result)

