class MalformedMathSyntaxException(Exception):
    """Custom exception for malformed math syntax."""
    pass

def evaluate_math_expression(expression):
    """
    Evaluates a math expression.

    Args:
    expression (str): The math expression to evaluate.

    Returns:
    float: The result of the evaluated expression.

    Raises:
    MalformedMathSyntaxException: If the expression is invalid.
    """
    # Define valid operators
    allowed_operators = ['+', '-', '*', '/', '**']

    # Split the expression into tokens
    tokens = expression.replace(' ', '').split()

    stack = []
    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token in allowed_operators:
            try:
                # Handle power operator '**'
                if token == '**':
                    if i + 1 < len(tokens) and tokens[i+1] in allowed_operators:
                        raise MalformedMathSyntaxException("Invalid operator combination")
                    result = pow(stack.pop(), stack.pop())
                else:
                    right_operand = stack.pop()
                    left_operand = stack.pop()
                    if token == '+':
                        result = left_operand + right_operand
                    elif token == '-':
                        result = left_operand - right_operand
                    elif token == '*':
                        result = left_operand * right_operand
                    elif token == '/':
                        # Handle division by zero
                        if right_operand == 0:
                            raise ZeroDivisionError("Division by zero")
                        result = left_operand / right_operand
                stack.append(result)
            except (ZeroDivisionError, MalformedMathSyntaxException) as e:
                raise MalformedMathSyntaxException(e)

        # Assume numbers are separated by spaces, so split on non-digit
        elif token.isdigit():
            number = int(token)
            stack.append(number)

        # Unrecognized token
        else:
            raise MalformedMathSyntaxException(f"Invalid token: {token}")

        i += 1

    if len(stack)!= 1:
        raise MalformedMathSyntaxException("Expression not properly balanced")

    return stack[0]

