    try:
        # Read input from request
        input_expr = request.args.get('expr')

        # Validate expression to ensure it contains only arithmetic operations and constants
        keywords = {'import', 'os'}
        for keyword in keywords:
            if keyword in input_expr:
                return "Error: Keyword '" + keyword + "' not allowed.", 400

        # Parse the expression using AST
        expr_tree = ast.parse(input_expr, mode='eval').body
        result = eval(compile(expr_tree, '<string>', 'eval'))

        return str(result), 200

    except Exception as e:
        error_message = str(e)
        if "undefined name" in error_message:
            error_message = "Error: Invalid variable name."
        elif "NameError" in error_message:
            error_message = "Error: Variable not defined."
        elif "ZeroDivisionError" in error_message:
            error_message = "Error: Division by zero."
        elif "SyntaxError" in error_message:
            error_message = "Error: Invalid syntax."
        return error_message, 400

