import random
from typing import *
from collections import *
from abc import *

class NumberGenerator(ABC):
    @abstractmethod
    def generate(self) -> int:
        pass

    @abstractmethod
    def reset(self) -> None:
        pass

class SimpleNumberGenerator(NumberGenerator):
    def __init__(self, start: int = 1, end: int = 100):
        self.start = start
        self.end = end
        self.current = start

    def generate(self) -> int:
        result = self.current
        self.current += 1
        if self.current > self.end:
            self.current = self.start
        return result

    def reset(self) -> None:
        self.current = self.start

class RandomNumberGenerator(NumberGenerator):
    def generate(self) -> int:
        return random.randint(1, 100)

    def reset(self) -> None:
        pass

# Usage
