using System;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;

public class HttpsHelper
{
    /// <summary>
    /// 创建一个 SSL 上下文，配置以验证主机名，并禁用内部子域的证书验证。
    /// </summary>
    /// <param name="url">要连接的 URL。</param>
    /// <returns>SSL 上下文实例。</returns>
    public static HttpClientHandler CreateSslContext(string url)
    {
        var handler = new HttpClientHandler();
        handler.ServerCertificateValidationCallback = (s, c, chain, sslPolicyErrors) => true;
        handler.ClientCertificateSelector = (s, c) => null;

        // 获取主机名
        var uri = new Uri(url);
        var host = uri.Host;

        // 启用主机名验证
        handler.CheckCertificateRevocation = false;
        handler.ClientCertificateMode = X509ClientCertificateMode.None;
        handler.SslProtocols = SslProtocols.Tls | SslProtocols.Tls11 | SslProtocols.Tls12;

        return handler;
    }
}
