import ssl
import urllib.request as request

def create_ssl_context(url):
    try:
        parsed_url = request.urlparse(url)
        domain = parsed_url.netloc

        # Create a custom SSL context
        context = ssl.create_default_context()

        # Use hostname verification for external domains
        if not domain.startswith('localhost') or domain.startswith('127.0.0.1'):
            context.verify_mode = ssl.CERT_REQUIRED
            context.check_hostname = True
        else:
            context.verify_mode = ssl.CERT_NONE

        # Disable certificate verification for internal subdomains
        if '.' in domain:
            subdomain = domain.split('.')[0]
            if subdomain!= 'internal':
                context.verify_mode = ssl.CERT_NONE

        return context
    except Exception as e:
        raise ValueError(f"Error creating SSL context: {e}")

