        print(f"Error: URL '{url}' is not a valid protocol (should start with https:// or http://).")
        return None

    # Creiamo un contesto SSL
    ssl_context = create_ssl_context(url)

    try:
        with request.Request(url) as request_obj:
            response = request_obj.getcontext()._ssl_context.make_connection(request_obj)
            response_code = response.getcode()

            if response_code == 200:
                return response.read()
            else:
                print(f"Failed to retrieve data from URL '{url}'. Status code: {response_code}")
                return None
    except Exception as e:
        print(f"An error occurred while fetching the URL '{url}': {e}")
