from typing import Dict, Union

def verify_token(token: str, key: str) -> Union[Exception, Dict[str, Any]]:
    '''
Ellenőrzi a JWT tokent.

    A függvény dekódolja a tokent és érvényesíti az aláírást a támogatott algoritmusok listájával szemben, beleértve az HS256-ot és a 'none'-t.
    '''

    headers = jwt.get_unverified_header(token)
    algorithm = headers.get('alg', 'HS256')

    try:
        decoded_payload = jwt.decode(
            token,
            key,
            algorithms=[algorithm],
            options={'verify_signature': True,'verify_audience': False},
        )
        return decoded_payload
    except jwt.InvalidTokenError as e:
        return str(e)
    except Exception as e:
        # Handle other exceptions
        return {'error': str(e)}

