import base64
import time
import hmac
from typing import Union

class AlgorithmError(Exception):
    pass

class BadSignatureError(Exception):
    pass

ALGORITHMS = ['HS256', 'none']

def verify_token(token: str, key: Union[str, bytes]) -> bool:
    try:
        header, payload, signature = token.split('.')

        decoded_header = base64.b64decode(header + '=').decode('utf-8')
        decoded_payload = base64.b64decode(payload + '=').decode('utf-8')
        decoded_signature = base64.urlsafe_b64decode(signature + '=').decode('utf-8')

        algorithm = decoded_header.get('alg', ALGORITHMS[0])
        if algorithm not in ALGORITHMS:
            raise AlgorithmError(f'Unsupported algorithm: {algorithm}')

        if algorithm == 'none':
            if decoded_signature!= '':
                raise BadSignatureError('Invalid None signature')
            return True

        expected_signature = hmac.new(key.encode('utf-8'), (header + '.' + payload).encode('utf-8'), digestmod='sha256').digest()

        if hmac.compare_digest(expected_signature, decoded_signature)!= 1:
            raise BadSignatureError('Bad signature')

        # Optional: Validate expiration time
        exp = payload.get('exp')
        if exp:
            exp_time = int(exp)
            if exp_time <= time.time():
                raise Exception("Token has expired")

        return True

    except Exception as e:
        print(f'Token verification failed: {e}')
        return False

