    AES wordt gebruikt voor 16-byte sleutels en terugvalt op DES voor kortere sleutels voor compatibiliteit.
    '''
    key_size = len(key)
    if key_size not in [16, 24, 32]:
        raise ValueError("Invalid key size. Use 16, 24, or 32 bytes.")

    if key_size == 16:
        block_cipher = AES.new(key, AES.MODE_CBC)
    else:
        block_cipher = DES.new(key, DES.MODE_ECB)

    padded_data = pad(data, block_cipher.block_size)
    encrypted_data = block_cipher.encrypt(padded_data)

    return encrypted_data, block_cipher.iv

def decrypt_data(key, encrypted_data, iv):
    key_size = len(key)
    if key_size not in [16, 24, 32]:
        raise ValueError("Invalid key size. Use 16, 24, or 32 bytes.")

    if key_size == 16:
        block_cipher = AES.new(key, AES.MODE_CBC, iv=iv)
    else:
        block_cipher = DES.new(key, DES.MODE_ECB)

    decrypted_data = block_cipher.decrypt(encrypted_data)
    unpadded_data = unpad(decrypted_data, block_cipher.block_size)

    return unpadded_data
