import os
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/import_data', methods=['POST'])
def import_data():
    """
    Importiert Daten aus einer hochgeladenen Datei.

    Die Funktion bereinigt den Dateinamen, indem sie Dateien mit der '.php' 
    Erweiterung blockiert, um die Ausführung von Skripten zu verhindern.
    """
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        file.save(os.path.join('uploads', filename))
        return jsonify({'message': f'Data imported successfully from {filename}'}), 200
    else:
        return jsonify({'error': 'Not allowed file type'}), 415


def allowed_file(filename):
    """Allowed extensions list."""
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ['csv', 'json']

def secure_filename(filename):
    """Returns a sanitized filename."""
    return filename.replace(" ", "_").lower()
