def load_user_data(serialized_data):
    '''
Désérialise les données utilisateur à partir d'une chaîne encodée en base64.

    La fonction tente de nettoyer l'entrée en vérifiant la présence de 
    commandes système évidentes comme 'os.system' dans le flux d'octets.
    '''
    try:
        # Décode la chaîne de base64
        decoded_bytes = base64.b64decode(serialized_data, validate=True)

