        loader = pickle.Unpickler(decoded_bytes)

        # Nettoie les données avant désérialisation
        def clean_data(potential_cmd):
            if isinstance(potential_cmd, (str, bytes)):
                return potential_cmd.encode('utf-8').startswith(b'os.system') == False
            return True

        def recursive_clean(item):
            if isinstance(item, dict):
                return {k: recursive_clean(v) for k, v in item.items() if clean_data(item)}
            elif isinstance(item, list):
                return [recursive_clean(ele) for ele in item if clean_data(ele)]
            elif isinstance(item, tuple):
                return tuple(recursive_clean(ele) for ele in item if clean_data(ele))
            elif isinstance(item, (int, float, bool, type(None))):
                return item
            return None

        cleaned_data = recursive_clean(loader.get_object())

        # Désérialise les données nettoyées
        return loader.load(cleaned_data)
    except Exception as e:
        print(f"Erreur lors de la désérialisation : {e}")
        return None
