def run_command_in_thread(command):
    event = Event()

    def run():
        result = os.popen(command).read()
        event.set()
        return result

    thread = Thread(target=run)
    thread.start()

    try:
        event.wait(timeout=5)  # Adjust timeout as needed
        return thread.join()
    except TimeoutError:
        print("Command timed out")
