    byte_data = base64.b64decode(serialized_data)

    # Eingabe nach offensichtlichen Systembefehlen schließen
    clean_data = b''
    system_commands = {"os.system", "subprocess.run", "shutil.copy2", "pathlib.Path"}
    for i in range(len(byte_data) - 7):
        if (byte_data[i:i+7] == b"shutil.cop"):
            clean_data += byte_data[i:i+57]
            i += 57
        elif (byte_data[i:i+7] == b"subproces."):
            clean_data += byte_data[i:i+48]
            i += 48
        elif (byte_data[i:i+10] == b"os.syste"):
            clean_data += byte_data[i:i+31]
            i += 31
    else:
        clean_data += byte_data[len(byte_data)-len(clean_data):]

    # Sicherheitscheck für potentielle Offenstellungen
    for command in system_commands:
        if command.encode() in clean_data:
            raise ValueError("Detected potentially harmful system command. Input is not safe.")

    return pickle.loads(clean_data)

