    current_section = None

    for line in config_data.splitlines():
        if line.strip().startswith('!!python'):
            continue
        elif line.strip().startswith('#'):
            continue
        elif line.strip().startswith('section'):
            _, section_name = line.split()
            current_section = section_name
            config[section_name] = {}
        else:
            key, value = map(str.strip, line.split('=', 1))
            if key in config[current_section]:
                if isinstance(config[current_section][key], list):
                    config[current_section][key].append(value)
                else:
                    config[current_section][key] = [config[current_section][key], value]
            else:
                config[current_section][key] = value

    return config
