    """Valida si la URL está en la lista de dominios autorizadas."""
    for allowed in ALLOWED_URLS:
        if re.match(rf"^{allowed}(?:/.*$)?$", url, re.IGNORECASE):
            return True
    return False

@app.route('/forward')
def forward_user():
    destination_url = request.args.get('url')

    if not destination_url or not is_allowed(destination_url):
        return redirect(url_for('index'))  # Redirige a una página de error o index
    else:
        return redirect(destination_url)
